// Blog posts batch 6 (2026-10-16): lamb roasts, whole lamb and mutton. Rules in posts-blog.js.
import { BLOG_KEYWORDS } from './posts-blog-keywords.js'

const meta = (slug) => ({ slug, kw: BLOG_KEYWORDS[slug].focus, keywords: BLOG_KEYWORDS[slug].keywords, date: '2026-10-16', updated: '2026-10-16' })

export const BLOG_POSTS_6 = [
  {
    ...meta('leg-of-lamb-cooking-time'),
    title: 'Leg of Lamb Cooking Time: Roasting Charts and Slow-Roast Guide',
    seoTitle: 'Leg of Lamb Cooking Time: Easy Roast Guide',
    excerpt: `Leg of lamb cooking time charts for bone-in, boneless and butterflied legs, a classic lamb leg roast method, and how to slow roast a lamb leg until tender.`,
    body: [
      ['p', `A roast leg of lamb is the centrepiece of countless Australian Sunday lunches, Eid tables and family celebrations. It is generous, easy to carve and full of flavour, and it is surprisingly simple to get right once you know the timing. This guide gives you a leg of lamb cooking time chart for every size and doneness, explains the difference between a classic pink roast and a slow roast lamb leg, and covers seasoning, resting and carving so your roast is perfect every time.`],
      ['h2', `Choosing your leg of lamb`],
      ['p', `Legs come in several forms, and each cooks a little differently:`],
      ['ul', [
        `[Bone-in leg](/product/leg-of-lamb-for-sale-bone-in/): the classic. The bone adds flavour and helps the meat cook evenly; typical weight 2 to 2.8 kg.`,
        `[Half leg, bone-in](/product/half-lamb-leg-bone-in/): ideal for smaller households, about 1.2 to 1.5 kg.`,
        `[Boned and rolled leg](/product/lamb-leg-boned-and-rolled/): easy to carve into neat slices, and can be stuffed.`,
        `[Butterflied leg](/product/lamb-leg-butterflied/): boned and opened flat; cooks quickly on the barbecue or in a hot oven.`,
        `[Milk-fed lamb leg](/product/milk-fed-lamb-leg-bone-in/): from younger lamb, very tender and delicate.`,
      ]],
      ['h2', `Leg of lamb cooking time chart`],
      ['p', `For a classic pink lamb leg roast, heat the oven to 200°C, put the lamb in, then reduce to 180°C (160°C fan). Times are per 500 g, starting from lamb that has been out of the fridge for about an hour.`],
      ['table', { caption: 'Leg of lamb cooking time at 180°C (per 500 g)', head: ['Doneness', 'Minutes per 500 g', 'Remove at', 'After resting'], rows: [['Rare', '15 to 18', '48°C', '52°C'], ['Medium-rare', '20 to 22', '53°C', '57°C'], ['Medium', '25', '58°C', '62°C'], ['Well done', '30 to 35', '66°C', '70°C']] }],
      ['p', `So a 2.4 kg bone-in leg cooked to medium-rare needs about 95 to 105 minutes. Boneless rolled legs cook slightly faster per kilo, and butterflied legs much faster, about 30 to 40 minutes at 200°C, because they are thin. The temperature column is always your most reliable guide; our [lamb cooking temperature](/blog/lamb-cooking-temperature/) guide explains how to use a thermometer.`],
      ['h2', `Classic lamb leg roast`],
      ['p', `Serves six to eight.`],
      ['ul', [
        `1 bone-in leg of lamb, about 2.2 to 2.5 kg`,
        `6 cloves garlic, sliced, and a few sprigs of rosemary`,
        `2 tablespoons olive oil, salt and cracked black pepper`,
        `Zest of 1 lemon`,
        `1 kg potatoes and 2 onions, cut into wedges, for roasting underneath`,
      ]],
      ['p', `Take the lamb out of the fridge an hour before cooking. Pat it dry. With a small knife, make 12 to 15 small slits all over the lamb and push a slice of garlic and a few rosemary leaves into each. Rub with olive oil, lemon zest, plenty of salt and pepper. Place the potatoes and onions in a roasting tin, toss with oil and salt, and sit the lamb on top so the juices drip onto the vegetables.`],
      ['p', `Roast at 200°C for 15 minutes, then reduce to 180°C and roast for the remaining time from the chart. Check the temperature in the thickest part, away from the bone. Rest for 20 minutes, loosely covered with foil, while you turn the oven up to crisp the potatoes.`],
      ['h2', `Roast lamb leg slow: the fall-apart method`],
      ['p', `A roast lamb leg slow cooked for several hours becomes tender enough to pull apart with a spoon. It is the style loved in Greek, Lebanese and many South Asian homes, and it is very forgiving. Rub the leg with olive oil, garlic, lemon, oregano or your favourite spice mix. Place it in a deep roasting dish with onion wedges and a cup of stock or water, cover tightly with baking paper and two layers of foil, and roast at 150°C for 5 to 6 hours. Uncover for the last 30 minutes at 200°C to brown. The meat will be well done and falling off the bone, with rich juices for spooning over.`],
      ['p', `Slow roasting also works brilliantly with lamb shoulder; see our [slow roast lamb slow cooker](/blog/slow-roast-lamb-slow-cooker/) guide.`],
      ['h2', `Flavour ideas`],
      ['ul', [
        `Garlic and rosemary: the Australian classic.`,
        `Greek: lemon, oregano, garlic and olive oil, with potatoes roasted in the juices.`,
        `Middle Eastern: cumin, coriander, sumac, cinnamon and pomegranate molasses.`,
        `Indian raan: yoghurt, ginger, garlic, garam masala and chilli, marinated overnight and slow roasted.`,
        `Moroccan: ras el hanout, honey and preserved lemon.`,
      ]],
      ['h2', `Resting and carving`],
      ['p', `Rest the lamb for at least 15 to 20 minutes. To carve a bone-in leg, hold the shank bone with a cloth, and slice the meat from the thickest part at a slight angle, working towards the bone. Turn the leg over and repeat. For a rolled leg, remove the string and slice across into neat rounds.`],
      ['h2', `Halal meat lamb for family celebrations`],
      ['p', `For Eid, aqeeqah and other celebrations, families often look for halal meat lamb they can trust, cut fresh and delivered on time. A whole leg feeds six to eight people, and two legs roasted side by side are easy to manage for a bigger crowd. For very large gatherings, a [whole lamb](/whole-lamb-aqeeqah-qurbani/) may be better value. All of our lamb is certified halal by Halal Control Australia.`],
      ['h2', `Price of lamb in Australia`],
      ['p', `The price of lamb in Australia changes with the season and market conditions, and legs are usually priced in the middle of the range: more affordable than racks and backstraps, a little more than shoulder. Whole legs tend to be better value per kilo than leg steaks. Our [halal lamb range](/shop/lamb/) shows current prices per kilo on every product page, so you can compare before ordering.`],
      ['h2', `Leg of lamb questions`],
      ['h3', `How much lamb per person?`],
      ['p', `Allow about 350 to 400 g of bone-in leg per person, or 200 to 250 g of boneless leg.`],
      ['h3', `Should I cover lamb when roasting?`],
      ['p', `Leave it uncovered for a classic pink roast so the outside browns. Cover it tightly for a slow roast, then uncover at the end.`],
      ['h3', `Can I cook a leg of lamb from frozen?`],
      ['p', `It is not recommended. Thaw it in the fridge for 24 to 48 hours first, so it cooks evenly.`],
      ['h3', `How do I keep it juicy?`],
      ['p', `Do not overcook it, use a thermometer, and rest it properly before carving.`],
      ['h3', `What do I do with leftovers?`],
      ['p', `Leftover roast lamb makes excellent wraps with hummus and salad, shepherd's pie, a quick lamb curry or a warm salad with roasted vegetables and feta. Keep it covered in the fridge and use within three days.`],
      ['h2', `Buy halal leg of lamb online`],
      ['p', `Bone-in, half, rolled, butterflied and milk-fed legs are all in our [halal lamb range](/shop/lamb/), delivered chilled from Greenacre, Sydney, to anywhere in Australia, with free delivery on orders over $500.`],
    ],
  },
  {
    ...meta('rack-of-lamb-cooking-time'),
    title: 'Rack of Lamb Cooking Time: A Foolproof Rack of Lamb Recipe',
    seoTitle: 'Rack of Lamb Cooking Time and Easy Recipe',
    excerpt: `Rack of lamb cooking time for every doneness, a herb-crusted rack of lamb recipe, searing and roasting tips, and how to carve a lamb rack into cutlets.`,
    body: [
      ['p', `A rack of lamb looks like a restaurant dish, but it is one of the quickest and easiest roasts you can make. It cooks in under 30 minutes, needs very little preparation and carves into beautiful pink cutlets. The key is getting the timing right, because racks are small and lean and can overcook quickly. This guide gives you a reliable rack of lamb cooking time chart, a herb-crusted rack of lamb recipe, and tips for searing, resting and carving.`],
      ['h2', `What is a rack of lamb?`],
      ['p', `A rack is the section of the lamb's ribs containing the tender eye of loin. A full lamb rack of eight ribs usually weighs 600 to 900 g and serves two to three people. Racks are often "frenched", which means the fat and meat are trimmed from the end of the bones for a clean, elegant look. Our [frenched lamb rack](/product/lamb-rack-frenched/) is ready to cook, and [goat frenched racks](/product/goat-frenched-rack/) are a delicious alternative. When sliced between the bones, a rack becomes [lamb cutlets](/product/frenched-lamb-cutlets-price/).`],
      ['h2', `Rack of lamb cooking time chart`],
      ['p', `These times are for an 8-rib rack (600 to 800 g), seared first, then roasted at 200°C (180°C fan).`],
      ['table', { caption: 'Rack of lamb cooking time after searing, at 200°C', head: ['Doneness', 'Oven time', 'Remove at', 'After resting'], rows: [['Rare', '10 to 12 minutes', '48°C', '52°C'], ['Medium-rare', '13 to 16 minutes', '53°C', '57°C'], ['Medium', '17 to 20 minutes', '58°C', '62°C'], ['Well done', '22 to 25 minutes', '65°C', '70°C']] }],
      ['p', `Racks are at their best medium-rare to medium. A thermometer inserted into the centre of the eye, from the end, is the most accurate way to check. Larger or double racks need a few more minutes; our [lamb cooking temperature](/blog/lamb-cooking-temperature/) guide explains carryover cooking.`],
      ['h2', `Herb-crusted rack of lamb recipe`],
      ['p', `Serves four.`],
      ['ul', [
        `2 frenched lamb racks (8 ribs each)`,
        `Salt, pepper and 1 tablespoon olive oil`,
        `2 tablespoons Dijon mustard`,
        `1 cup fresh breadcrumbs`,
        `3 tablespoons finely chopped parsley, 1 tablespoon each rosemary and thyme`,
        `2 cloves garlic, crushed, zest of 1 lemon and 2 tablespoons melted butter or olive oil`,
      ]],
      ['h3', `Method`],
      ['p', `Take the racks out of the fridge 30 minutes before cooking and heat the oven to 200°C. Score the fat in a fine crosshatch and season well. Heat the oil in a heavy pan over medium-high heat and sear the racks fat-side down for 3 to 4 minutes until golden, then briefly sear the other sides. Let them cool for a few minutes.`],
      ['p', `Mix the breadcrumbs, herbs, garlic, lemon zest, butter and a pinch of salt. Brush the fat side of each rack with mustard and press the crumb mixture firmly on top. Place the racks on a tray, crust side up, with the bones interlocked or pointing upwards. Roast for 13 to 16 minutes for medium-rare, until the crust is golden. Rest for 8 to 10 minutes before carving.`],
      ['h2', `Other ways to flavour a rack`],
      ['ul', [
        `Garlic and rosemary: rub with olive oil, crushed garlic and chopped rosemary before searing.`,
        `Pistachio and herb crust: replace half the breadcrumbs with chopped pistachios.`,
        `Middle Eastern: rub with cumin, sumac, garlic and lemon; serve with pomegranate and herbs.`,
        `Harissa and honey glaze: brush on in the last 5 minutes of roasting.`,
        `Indian: marinate in yoghurt, garam masala and ginger-garlic paste overnight.`,
      ]],
      ['h2', `Carving a rack of lamb`],
      ['p', `After resting, stand the rack upright with the bones pointing up and slice down between the bones with a sharp knife to make individual cutlets, or cut into double cutlets for a more generous serve. Arrange them on a warm platter and spoon over any resting juices.`],
      ['h2', `What to serve with rack of lamb`],
      ['p', `Rack of lamb pairs beautifully with creamy mashed potato or a potato gratin, roasted baby carrots, green beans, minted peas, ratatouille or a simple rocket salad. A red pepper sauce, salsa verde, mint sauce or a quick pan jus made from the searing pan all work well.`],
      ['h2', `Halal meats for a special dinner`],
      ['p', `A rack of lamb is one of the most impressive halal meats you can serve for a special dinner, an anniversary or Eid. It takes less than half an hour, looks stunning, and pairs with almost any side. For a bigger crowd, cook several racks side by side on one tray; the timing stays the same, as long as there is space between them.`],
      ['h2', `Want more cuts? Buy a lamb`],
      ['p', `Lamb racks are a premium cut, and each animal has only two. If your family loves racks, cutlets and chops, it can make sense to buy a lamb, either whole or half, and have it cut into racks, chops, legs, shoulders and shanks. You get every cut at a lower average price per kilo. See our [whole lamb carcass](/product/whole-lamb-carcass/), [half lamb carcass](/product/half-lamb-carcass/) and [quarter lamb](/blog/quarter-lamb-buying-guide/) guide.`],
      ['h2', `Rack of lamb questions`],
      ['h3', `Do I have to sear the rack first?`],
      ['p', `Searing gives a golden, flavourful crust and renders the fat cap. You can skip it and roast at 220°C instead, but the result is less crisp.`],
      ['h3', `How many people does a rack serve?`],
      ['p', `An 8-rib rack serves two to three people; allow three to four cutlets per adult.`],
      ['h3', `Can I cook it on the barbecue?`],
      ['p', `Yes. Sear over high heat, then move to indirect medium heat with the lid closed for 12 to 18 minutes, checking the temperature.`],
      ['h3', `Why is my rack tough?`],
      ['p', `It is almost always overcooked. Racks are lean, so even a few extra minutes can dry them out. Use a thermometer and rest them well.`],
      ['h3', `Can I prepare it ahead?`],
      ['p', `Yes. Sear the racks and apply the crust up to 4 hours ahead, keep them covered in the fridge, and roast just before serving, adding a few minutes to the time.`],
      ['h2', `A quick pan jus`],
      ['p', `While the racks rest, make a simple jus in the searing pan. Pour off most of the fat, add a finely chopped shallot and cook for a minute, then add a crushed garlic clove and a sprig of rosemary. Pour in 200 ml of lamb or beef stock and a teaspoon of red currant jelly or honey, scrape up the browned bits and simmer until reduced by half. Strain, season, and stir in any resting juices from the lamb. Spoon it over the carved cutlets just before serving.`],
      ['p', `For a fresher option, make a mint and parsley salsa verde with capers, garlic, lemon juice and olive oil. Its sharp, herby flavour balances the richness of the lamb beautifully.`],
      ['h2', `Buy halal lamb racks online`],
      ['p', `Frenched lamb racks, cutlets and goat racks are in our [halal lamb range](/shop/lamb/) and [goat range](/shop/goat-meat-for-sale/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('lamb-kofta-wraps'),
    title: 'Lamb Kofta Wraps: Recipe, Sauces and What to Serve',
    seoTitle: 'Lamb Kofta Wraps: Easy Recipe and Sides',
    excerpt: `How to make lamb kofta wraps with spiced, grilled koftas, garlic yoghurt and salad, plus what to serve with lamb koftas for an easy dinner or party spread.`,
    body: [
      ['p', `Lamb kofta wraps are one of the easiest and most satisfying dinners you can make. Spiced lamb mince, shaped around skewers and grilled until charred and juicy, is wrapped in warm flatbread with crisp salad, pickles and a creamy garlic or yoghurt sauce. They are perfect for weeknights, barbecues and parties, and children love building their own. This guide covers the kofta recipe, the wrap, sauces, and plenty of ideas for what to serve with lamb koftas.`],
      ['h2', `What are koftas?`],
      ['p', `Kofta (also kofte, köfte or kufta) is a family of spiced meatballs and meat skewers found across the Middle East, Turkey, Central Asia and South Asia. Lamb koftas are typically made from minced lamb mixed with onion, herbs and warm spices, shaped into sausages or patties, and grilled. In Lebanon, kafta is often shaped around flat skewers; in Turkey, köfte might be small patties; in India, kofta are usually simmered in a curry sauce.`],
      ['h2', `Lamb kofta recipe`],
      ['p', `Makes 8 to 10 koftas, enough for four to five wraps.`],
      ['ul', [
        `750 g [lamb mince](/product/ground-lamb-meat-mince/)`,
        `1 onion, grated and squeezed dry`,
        `2 cloves garlic, crushed`,
        `1 large handful each of parsley and mint, finely chopped`,
        `2 teaspoons ground cumin and 1 teaspoon ground coriander`,
        `1 teaspoon sweet paprika, 1/2 teaspoon each of cinnamon and allspice`,
        `1/2 teaspoon chilli flakes (optional) and 1 1/2 teaspoons salt`,
      ]],
      ['p', `Combine everything in a bowl and knead with your hands for 2 to 3 minutes until the mixture becomes slightly sticky; this helps the koftas hold together on the grill. Chill for 30 minutes. With wet hands, divide the mixture into 8 to 10 portions and shape each around a flat metal skewer or soaked bamboo skewer into a sausage about 12 cm long. Chill again for 15 minutes.`],
      ['p', `Grill over medium-high heat on a barbecue or chargrill pan for 8 to 10 minutes, turning every 2 minutes, until browned and cooked through (71°C in the centre). Short on time? Our ready-made [lamb kofta](/product/lamb-kofta/) is seasoned and ready to grill.`],
      ['h2', `Building lamb kofta wraps`],
      ['p', `Warm flatbreads, such as Lebanese bread, pita or soft wraps, on the grill for a few seconds each side. Spread with garlic sauce or yoghurt sauce, add shredded lettuce, sliced tomato, cucumber, red onion and pickles, then slide the kofta off its skewer onto the bread. Add a sprinkle of sumac and fresh herbs, roll tightly and wrap the bottom in baking paper. Cut in half to serve.`],
      ['h2', `Three sauces`],
      ['h3', `Garlic yoghurt`],
      ['p', `Mix 1 cup thick Greek yoghurt with 1 crushed garlic clove, a squeeze of lemon, a pinch of salt and some chopped mint. Quick, fresh and cooling.`],
      ['h3', `Tahini sauce`],
      ['p', `Whisk 1/3 cup tahini with the juice of a lemon, a crushed garlic clove, a pinch of salt and enough cold water to make a smooth, pourable sauce.`],
      ['h3', `Toum (Lebanese garlic sauce)`],
      ['p', `Blend 1/2 cup peeled garlic cloves with 1 teaspoon salt and 2 tablespoons lemon juice, then drizzle in 1 1/2 cups of neutral oil very slowly while blending, alternating with a little more lemon juice and ice water, until fluffy and white. It keeps for weeks in the fridge.`],
      ['h2', `What to serve with lamb koftas`],
      ['p', `If you are wondering what to serve with lamb koftas beyond a wrap, here are some favourites:`],
      ['ul', [
        `Tabbouleh: parsley, mint, tomato, onion and fine bulgur with lemon and olive oil.`,
        `Fattoush: crisp lettuce, cucumber, tomato, radish and toasted pita with a sumac dressing.`,
        `Hummus and baba ganoush with warm flatbread.`,
        `Saffron rice or herbed couscous.`,
        `Grilled vegetables, such as eggplant, zucchini, capsicum and onion.`,
        `Pickled turnips, cucumbers and chillies.`,
      ]],
      ['h3', `What to eat with lamb koftas for a lighter meal`],
      ['p', `For a lighter option, think about what to eat with lamb koftas without bread: a big Greek salad, a grain bowl with quinoa, roasted vegetables and tahini, or crisp lettuce cups with yoghurt sauce and pickles. Koftas are also delicious with cauliflower rice or a simple cucumber and tomato salad.`],
      ['h2', `Lamb kofta wraps for a party`],
      ['p', `Kofta wraps are perfect for entertaining. Shape the koftas the day before and keep them covered in the fridge. Set up a wrap bar with warm bread, sauces, salads and pickles, grill the koftas as guests arrive, and let everyone build their own. Allow two koftas per adult. For a bigger celebration, add [lamb skewers](/blog/lamb-skewers/) or a [whole lamb](/whole-lamb-aqeeqah-qurbani/) to the menu.`],
      ['h2', `The halal butchery difference`],
      ['p', `Good koftas start with good mince. At the halal butchery level, freshly minced lamb with the right amount of fat makes all the difference: too lean and the koftas are dry; too fatty and they fall apart. Our lamb mince is minced fresh in Greenacre, Sydney and certified halal by Halal Control Australia.`],
      ['h2', `Planning a big celebration? Buy whole lamb`],
      ['p', `For Eid, weddings and aqeeqah, many families buy whole lamb and use every part: legs for roasting, chops for grilling, shoulders for slow cooking and trimmings minced for koftas. It is economical and ensures nothing goes to waste. Our [whole lamb carcass](/product/whole-lamb-carcass/) can be cut to your requirements; see our [whole lamb](/whole-lamb-aqeeqah-qurbani/) page for options.`],
      ['h2', `Lamb kofta questions`],
      ['h3', `Why do my koftas fall off the skewers?`],
      ['p', `The mixture was too wet or not kneaded enough, or it was not chilled. Squeeze the grated onion well, knead for a few minutes and chill before and after shaping.`],
      ['h3', `Can I bake koftas?`],
      ['p', `Yes. Bake on a lined tray at 220°C for 15 to 18 minutes, turning once, then finish under the grill for colour.`],
      ['h3', `Can I freeze koftas?`],
      ['p', `Yes, raw or cooked. Freeze raw koftas on a tray, then bag them for up to three months. Thaw in the fridge before cooking.`],
      ['h2', `Pickles and extras`],
      ['p', `Pickles add a sharp, crunchy contrast to rich lamb koftas. Lebanese pink pickled turnips, pickled cucumbers and pickled chillies are traditional, and quick pickled red onions take just 20 minutes: slice a red onion thinly, cover with equal parts vinegar and hot water, add a teaspoon each of sugar and salt, and leave to stand. Other great extras include crumbled feta, pomegranate seeds, toasted pine nuts, a pinch of sumac and a drizzle of chilli oil.`],
      ['h2', `Buy halal lamb mince and kofta`],
      ['p', `Lamb mince and ready-made lamb kofta are in our [halal lamb range](/shop/lamb/), delivered chilled from Greenacre, Sydney, to anywhere in Australia. For more ideas, see our [lamb mince recipes](/blog/lamb-mince-recipes/).`],
    ],
  },
  {
    ...meta('lamb-neck-recipes'),
    title: 'Lamb Neck Recipes: Slow-Cooked Dishes Full of Flavour',
    seoTitle: 'Lamb Neck Recipes: 5 Tender Slow-Cooked Dishes',
    excerpt: `Five lamb neck recipes: Moroccan tagine, Irish stew, Indian curry, slow-braised neck with lentils and a recipe for neck of lamb roasted until it falls apart.`,
    body: [
      ['p', `Lamb neck is one of the most underrated cuts in the butcher's cabinet. It is inexpensive, deeply flavoured and, when cooked slowly, meltingly tender, with a rich, gelatinous sauce that rivals much more expensive cuts. Chefs have embraced it for good reason. This guide explains how to cook lamb neck and shares five lamb neck recipes, from a Moroccan tagine to a classic Irish stew, plus tips for getting the most from this hard-working cut.`],
      ['h2', `What is lamb neck?`],
      ['p', `The neck is a well-exercised muscle running from the head to the shoulder. It is marbled with fat and full of connective tissue, which makes it tough if cooked quickly, but perfect for slow cooking. Lamb neck is sold in two main forms: neck chops or rosettes, cut across the bone, and neck fillet, the boneless eye of the neck. Bone-in neck gives the richest sauce. Our [lamb neck](/product/lamb-neck/) is ready for braising.`],
      ['h2', `How to cook lamb neck`],
      ['p', `Lamb neck needs long, slow, moist cooking: braising, stewing or slow roasting at 150 to 160°C for 2 to 3 hours, or 7 to 8 hours on low in a slow cooker. Brown it well first for flavour, cook it gently in liquid, and it is ready when the meat slips easily off the bone. Like most slow-cooked dishes, neck tastes even better the next day.`],
      ['h2', `1. Moroccan lamb neck tagine`],
      ['p', `Brown 1.5 kg lamb neck pieces. Soften a sliced onion with garlic and ginger, add 2 teaspoons ras el hanout, 1 teaspoon each cumin and cinnamon, and a pinch of saffron. Return the lamb, add 2 cups of stock, a can of chopped tomatoes, a handful of dried apricots and a strip of preserved lemon. Cover and simmer gently, or bake at 160°C, for 2.5 hours. Finish with toasted almonds and coriander. Serve with couscous.`],
      ['h2', `2. Irish-style lamb neck stew`],
      ['p', `Layer browned neck chops with sliced onion, carrots and potatoes in a heavy pot, seasoning each layer. Add thyme and bay leaves and enough stock to almost cover. Cover and cook at 150°C for 2.5 to 3 hours until the meat is falling off the bone and the potatoes have thickened the broth. Serve in deep bowls with crusty bread.`],
      ['h2', `3. Lamb neck curry`],
      ['p', `Lamb neck is a favourite for curry in South Asian homes because the bones enrich the sauce. Fry 2 onions until deep golden, add ginger-garlic paste, then garam masala, cumin, coriander, turmeric and chilli. Add 1.2 kg neck pieces and brown for 5 minutes, then tomatoes and a little yoghurt. Add water to just cover, and simmer, covered, for 2 hours until tender. Finish with coriander and green chilli and serve with rice or roti.`],
      ['h2', `4. Slow-braised lamb neck with lentils`],
      ['p', `Brown 4 pieces of bone-in neck. Soften onion, carrot and celery, add garlic and rosemary, then 1 cup of rinsed brown or green lentils, a can of chopped tomatoes and 3 cups of stock. Nestle the lamb into the lentils, cover and braise at 160°C for 2.5 hours. The lentils soak up the rich juices. Finish with lemon zest and parsley, and serve with a spoon of yoghurt.`],
      ['h2', `5. Recipe for neck of lamb, slow roasted`],
      ['p', `This recipe for neck of lamb treats the boneless neck fillet like a mini roast. Rub 2 neck fillets with olive oil, garlic, smoked paprika, cumin, salt and pepper. Sear all over, then place in a small roasting dish with sliced onion and 1/2 cup of stock. Cover tightly and roast at 150°C for 2.5 hours, then uncover, baste and roast at 200°C for 15 minutes to glaze. Slice thickly and serve with flatbread, yoghurt and a sharp salad.`],
      ['h2', `More lamb neck dishes`],
      ['p', `Beyond these five, there are plenty of other lamb neck dishes to explore: Scotch broth, Persian khoresh with split peas and dried lime, Turkish stews with eggplant, Greek lamb with orzo, and Chinese-style braises with star anise and soy. Neck is also excellent in soup; see our [lamb shank soup](/blog/lamb-shank-soup/) recipe and swap in neck pieces.`],
      ['h2', `Tips for cooking lamb neck`],
      ['ul', [
        `Brown well in batches for colour and flavour.`,
        `Keep the liquid at a bare simmer; boiling toughens the meat.`,
        `Skim the fat or chill the dish overnight and lift off the set fat.`,
        `Season at the end, as the sauce concentrates during cooking.`,
        `Use bone-in pieces for the richest sauce.`,
      ]],
      ['h2', `Halal meat butchers who know their cuts`],
      ['p', `Good halal meat butchers will tell you that neck is one of the best-value cuts on the lamb. It needs a little patience, but rewards you with flavour that leaner, pricier cuts cannot match. Our butchers in Greenacre, Sydney cut neck chops and fillets to order, and every product is certified halal by Halal Control Australia.`],
      ['h2', `Buy whole lamb meat for the best value`],
      ['p', `If you cook a lot of slow-cooked lamb, consider buying a whole or half lamb. When you buy whole lamb meat, you get the neck, shoulders and shanks for slow cooking along with the legs, racks and chops, all at a better average price per kilo. See our [whole lamb carcass](/product/whole-lamb-carcass/) and [quarter lamb](/blog/quarter-lamb-buying-guide/) guide.`],
      ['h2', `Lamb neck questions`],
      ['h3', `Is lamb neck fatty?`],
      ['p', `It has a fair amount of marbling, which keeps it moist during slow cooking. Skim the fat after cooking for a lighter dish.`],
      ['h3', `How much lamb neck per person?`],
      ['p', `Allow about 350 to 400 g of bone-in neck per person, or 200 g of boneless fillet.`],
      ['h3', `Can I grill lamb neck?`],
      ['p', `Thin slices of neck fillet can be grilled after marinating, but bone-in neck should always be slow cooked.`],
      ['h3', `Can I freeze cooked lamb neck?`],
      ['p', `Yes, for up to three months in its sauce. Thaw overnight in the fridge and reheat gently.`],
      ['h2', `Planning ahead`],
      ['p', `Because lamb neck takes a few hours, it suits weekend cooking. Make a big batch on Sunday, cool it quickly, and portion it into containers for easy weeknight dinners. The flavour improves after a day or two in the fridge, and the fat sets on top so you can lift it off easily before reheating.`],
      ['h2', `Buy halal lamb neck online`],
      ['p', `Lamb neck, osso buco and shanks are in our [halal lamb range](/shop/lamb/), delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('how-to-cook-lamb-ribs-in-oven'),
    title: 'How to Cook Lamb Ribs in Oven: Sticky, Tender and Crisp',
    seoTitle: 'How to Cook Lamb Ribs in Oven: Easy Recipe',
    excerpt: `How to cook lamb ribs in oven so they are tender inside and crisp outside: a two-stage lamb ribs recipe oven method, spice rubs, glazes and serving ideas.`,
    body: [
      ['p', `Lamb ribs are one of the most delicious and affordable cuts of lamb. Rich, fatty and full of flavour, they become meltingly tender inside and wonderfully crisp outside when cooked the right way. The secret is a two-stage method: slow cooking to render the fat and soften the meat, followed by a blast of high heat to crisp and glaze. This guide explains how to cook lamb ribs in oven, step by step, with spice rubs, glazes and serving ideas.`],
      ['h2', `What are lamb ribs?`],
      ['p', `Lamb ribs, also called lamb breast or riblets, come from the belly of the lamb. Each lamb rib has a thin layer of meat between layers of fat, which makes them extremely flavoursome but means they need slow cooking to render the fat. They are sold as whole racks of [full plate ribs](/product/lamb-full-plate-ribs/) or cut into individual [lamb riblets](/product/lamb-riblets/).`],
      ['h2', `Why a two-stage method works`],
      ['p', `If you roast lamb ribs quickly at high heat, the outside burns before the fat has melted, leaving them chewy and greasy. If you only cook them low and slow, they become tender but lack crunch. Combining the two gives you the best of both: tender, juicy meat with a crisp, caramelised crust.`],
      ['h2', `Lamb ribs recipe oven method`],
      ['p', `Serves four.`],
      ['ul', [
        `1.5 to 2 kg lamb ribs (whole racks or riblets)`,
        `2 tablespoons olive oil`,
        `Spice rub (see below)`,
        `1 onion, sliced, and 1/2 cup water or stock`,
        `Glaze (optional, see below)`,
      ]],
      ['h3', `Stage 1: slow roast`],
      ['p', `Heat the oven to 160°C. Rub the ribs all over with oil and the spice rub. Place the sliced onion in a deep roasting dish, lay the ribs on top, and add the water or stock. Cover tightly with baking paper and foil and roast for 1.5 to 2 hours until the meat is very tender and much of the fat has rendered.`],
      ['h3', `Stage 2: crisp and glaze`],
      ['p', `Remove the ribs from the dish and pour off the fat and juices (save the juices for flavour). Increase the oven to 220°C. Place the ribs on a rack over a lined tray, brush with glaze if using, and roast for 15 to 20 minutes, turning once and brushing again, until crisp, sticky and deeply browned. Rest for 5 minutes, then cut between the bones and serve.`],
      ['h2', `Spice rubs`],
      ['ul', [
        `Middle Eastern: 2 teaspoons each cumin and coriander, 1 teaspoon each paprika and sumac, 1/2 teaspoon cinnamon, salt and pepper.`,
        `Smoky barbecue: smoked paprika, garlic powder, onion powder, brown sugar, salt and pepper.`,
        `Chinese five-spice: five-spice powder, garlic, ginger, salt and a little sugar.`,
        `Moroccan: ras el hanout, garlic, lemon zest and salt.`,
        `Indian: garam masala, Kashmiri chilli, turmeric, ginger-garlic paste and salt.`,
      ]],
      ['h2', `Glazes`],
      ['ul', [
        `Honey and soy: 3 tablespoons honey, 2 tablespoons soy sauce and a crushed garlic clove.`,
        `Pomegranate: 3 tablespoons pomegranate molasses, 1 tablespoon honey and a pinch of chilli.`,
        `Barbecue: your favourite barbecue sauce (check the label), thinned with a little of the cooking juices.`,
        `Harissa and honey: 2 tablespoons harissa, 2 tablespoons honey and a squeeze of lemon.`,
      ]],
      ['h2', `Tips for the best lamb ribs`],
      ['ul', [
        `Trim any very thick pieces of hard fat before cooking.`,
        `Cover tightly during the slow stage so the ribs steam and tenderise.`,
        `Drain the fat before crisping, or the ribs fry in it and become greasy.`,
        `Watch the glaze closely: honey and sugar can burn quickly at high heat.`,
        `Cut between the bones after resting with a sharp knife.`,
      ]],
      ['h2', `Serving ideas`],
      ['p', `Lamb ribs are rich, so serve them with fresh, sharp sides: a herb salad with lemon dressing, pickled red onions, tabbouleh, fattoush, or a crunchy slaw. Flatbread and garlic yoghurt are perfect for a Middle Eastern spread. For a barbecue feast, serve them alongside [lamb skewers](/blog/lamb-skewers/) and grilled corn.`],
      ['h2', `Meat shops halal: finding quality lamb ribs`],
      ['p', `Lamb ribs are not always easy to find in supermarkets, and many customers look for meat shops halal certified that stock them fresh. We cut lamb ribs daily in Greenacre, Sydney, and every product is certified halal by Halal Control Australia, with chilled delivery Australia-wide.`],
      ['h2', `The price of a lamb vs buying ribs`],
      ['p', `Lamb ribs are among the most economical cuts. If your family enjoys every part of the lamb, you might also consider the price of a lamb bought whole or half: you get the ribs along with legs, chops, racks, shanks and shoulders, at a lower average price per kilo. See our [whole lamb carcass](/product/whole-lamb-carcass/) and [half lamb carcass](/product/half-lamb-carcass/) for current prices.`],
      ['h2', `Lamb ribs questions`],
      ['h3', `How long do lamb ribs take in the oven?`],
      ['p', `About 1.5 to 2 hours covered at 160°C, plus 15 to 20 minutes uncovered at 220°C to crisp.`],
      ['h3', `Can I cook lamb ribs on the barbecue?`],
      ['p', `Yes. Slow cook them in the oven first, then finish on a hot barbecue for a smoky char. Alternatively, cook them over indirect heat with the lid closed for 2 hours, then over direct heat to crisp.`],
      ['h3', `Can I prepare them ahead?`],
      ['p', `Yes. Complete the slow-roasting stage a day ahead, refrigerate the ribs, then crisp and glaze them just before serving.`],
      ['h3', `Are lamb ribs very fatty?`],
      ['p', `They are a fatty cut, but much of the fat renders out during slow cooking. Draining the fat before crisping keeps them from being greasy.`],
      ['h2', `Slow cooker option`],
      ['p', `You can also do the first stage in a slow cooker. Rub the ribs with the spice mix, place them in the slow cooker with a sliced onion and a quarter cup of stock, and cook on low for 6 hours until tender. Lift them out carefully, as they will be very soft, drain off the fat, then glaze and crisp them in a 220°C oven or under a hot grill for 10 to 15 minutes. This is a convenient way to have ribs ready when you get home from work.`],
      ['h2', `Leftovers`],
      ['p', `Leftover lamb ribs are delicious shredded into wraps with yoghurt and pickles, or tossed through a warm grain salad. Reheat them in a hot oven so they stay crisp; the microwave makes them soft.`],
      ['h2', `Buy halal lamb ribs online`],
      ['p', `Lamb full plate ribs and riblets are in our [halal lamb range](/shop/lamb/), delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('lamb-spit-roast-guide'),
    title: 'Lamb Spit Roast Guide: How to Cook a Lamb on a Spit',
    seoTitle: 'Lamb Spit Roast Guide: Complete Step by Step',
    excerpt: `A complete lamb spit roast guide: choosing and preparing the lamb, securing lamb on a spit, charcoal and timing, seasoning, carving and feeding a crowd.`,
    body: [
      ['p', `A lamb on the spit is the ultimate celebration meal. Whether it is Easter, Eid, a wedding, a christening or a big family reunion, a whole lamb slowly turning over glowing coals draws everyone together. The process takes most of a day, but most of that is waiting while the spit turns. This lamb spit guide walks you through everything: choosing the lamb, preparing it, securing it, managing the fire, timing, seasoning and carving.`],
      ['h2', `Choosing the lamb`],
      ['p', `For spit roasting, a whole lamb of 14 to 20 kg (dressed weight) is ideal. It feeds about 30 to 40 people with sides, and it fits most home and hire spits. Larger lambs take longer and need heavier-duty equipment. Our [whole lamb carcass](/product/whole-lamb-carcass/) is delivered chilled and can be prepared for the spit; our [whole lamb](/whole-lamb-aqeeqah-qurbani/) page explains the options for celebrations, aqeeqah and Qurbani.`],
      ['h2', `Equipment you need`],
      ['ul', [
        `A spit rotisserie with a motor strong enough for the lamb's weight`,
        `A spit rod, U-bolts or spine clamps, and leg forks`,
        `Stainless steel wire or butcher's wire to secure the lamb`,
        `15 to 25 kg of lump charcoal (or gas, if your spit is gas-fired)`,
        `Heatproof gloves, a meat thermometer, tongs and a large carving board`,
        `A basting brush or a bunch of rosemary for basting`,
      ]],
      ['h2', `Preparing lamb on a spit`],
      ['p', `Securing lamb on a spit properly is the most important step: a loose lamb will slip as it turns and cook unevenly. Lay the lamb on a clean table. Push the spit rod through the body cavity, from the rear to the neck, keeping it as close to the spine as possible. Clamp the spine to the rod with U-bolts or spine clamps at two or three points. Tie the front legs together and the back legs together with wire, and secure them to the rod with leg forks. Wire the body cavity closed. Test that the lamb is balanced by turning the rod; adjust if one side drops.`],
      ['h2', `Seasoning`],
      ['p', `Keep it simple and generous. Rub the whole lamb, inside and out, with olive oil, lemon juice, plenty of salt, black pepper, garlic and dried oregano. Many Greek families also stuff the cavity with lemons, garlic and herbs. Lebanese and Middle Eastern cooks might use cumin, paprika, allspice and cinnamon. Make a basting mixture of olive oil, lemon juice, garlic, salt and oregano, and baste every 30 to 45 minutes during cooking.`],
      ['h2', `Managing the fire`],
      ['p', `Light the charcoal about 45 minutes before you plan to start cooking, and wait until it is covered in white ash. Spread it in two rows under the legs and shoulders, which are the thickest parts, with less directly under the thinner middle. The lamb should cook over moderate, steady heat, not fierce flames. Add fresh charcoal every 45 to 60 minutes to keep the temperature steady. If fat drips and causes flare-ups, move the coals slightly.`],
      ['h2', `How long does a lamb on the spit take?`],
      ['p', `A 15 to 18 kg lamb usually takes 4 to 6 hours, depending on its size, the heat and the weather. Start with the lamb higher above the coals for the first hour or two, then lower it closer for the last part of cooking to brown and crisp the skin. Check the internal temperature in the thickest part of the leg and shoulder: 65 to 70°C for slightly pink meat, or 75°C and above for well done, the style most families prefer. Rest the lamb on the spit, away from the heat, for 20 to 30 minutes before carving.`],
      ['h2', `Carving and serving`],
      ['p', `Remove the wires and clamps and lift the lamb off the rod onto a large board. Carve the legs and shoulders first, then the loin and ribs. Slice the meat into chunks and pile it on platters, sprinkling with salt, lemon and oregano. Serve with lemon potatoes, Greek salad, tzatziki, bread, rice and grilled vegetables.`],
      ['h2', `Halal food meat for big celebrations`],
      ['p', `For many Muslim families, a lamb on the spit is the centrepiece of Eid or a wedding feast, and choosing certified halal food meat is essential. Our lamb is certified halal by Halal Control Australia and cut in Greenacre, Sydney. For aqeeqah and Qurbani, our [whole lamb](/whole-lamb-aqeeqah-qurbani/) page explains how we can help.`],
      ['h2', `When to purchase whole lamb`],
      ['p', `Plan ahead. If you need to purchase whole lamb for an event, order at least a week ahead, especially around Eid, Easter and the Christmas holidays, when demand is high. Let us know the weight you need, whether you want it prepared for the spit, and your preferred delivery date. Chilled lamb should be kept at 0 to 4°C until you are ready to set up the spit.`],
      ['h2', `Spit roast alternatives`],
      ['p', `No spit? You can still feed a crowd with lamb. Slow-roast several [lamb shoulders](/product/lamb-shoulder-boned-and-rolled/) or [legs](/product/leg-of-lamb-for-sale-bone-in/) in the oven; our [leg of lamb cooking time](/blog/leg-of-lamb-cooking-time/) and [slow roast lamb](/blog/slow-roast-lamb-slow-cooker/) guides show you how. [Lamb skewers](/blog/lamb-skewers/) on a large barbecue are another great option.`],
      ['h2', `Lamb spit questions`],
      ['h3', `How many people does a whole lamb feed?`],
      ['p', `A 16 to 18 kg lamb feeds about 30 to 40 people as part of a meal with plenty of sides.`],
      ['h3', `Can I use a gas spit?`],
      ['p', `Yes. Gas spits are easier to control. Use moderate heat and expect similar cooking times.`],
      ['h3', `Should I wrap the lamb?`],
      ['p', `Some cooks wrap thinner areas, such as the belly, in foil for the first few hours to stop them overcooking, then remove the foil to brown.`],
      ['h3', `Can I hire a spit?`],
      ['p', `Many party hire companies rent spit rotisseries, often with charcoal and instructions. Check the motor's weight capacity before you book.`],
      ['h2', `A sample timeline`],
      ['p', `For a 1 pm lunch with a 16 kg lamb, start preparing the lamb on the spit at 6 am. Light the charcoal at 6.30 am, and start cooking at 7.15 am, with the lamb positioned high above the coals. Add fresh charcoal every 45 to 60 minutes and baste regularly. Around 10.30 am, start checking the temperature and lower the lamb closer to the heat to brown. Aim to take it off the heat by about 12.15 pm, rest it until 12.45 pm, then carve. Allowing a buffer of 30 to 60 minutes is wise, because outdoor cooking times vary with wind and weather.`],
      ['h2', `Order a whole lamb`],
      ['p', `Our [halal lamb range](/shop/lamb/) includes whole and half lamb carcasses, delivered chilled from Greenacre, Sydney, to anywhere in Australia, with free delivery on orders over $500.`],
    ],
  },
  {
    ...meta('quarter-lamb-buying-guide'),
    title: 'Quarter Lamb Buying Guide: What You Get and Is It Worth It?',
    seoTitle: 'Quarter Lamb Buying Guide: Complete Cuts List',
    excerpt: `A quarter lamb buying guide: what a quarter, half or lamb whole includes, the butcher lamb cuts of meat you get, freezer space, value and how to order.`,
    body: [
      ['p', `Buying lamb in bulk is one of the best ways to save money and keep your freezer stocked with a variety of cuts. A quarter lamb is often the first step for families, but it is worth knowing exactly what you get, how much freezer space you need and how it compares with buying a half or a whole lamb. This guide explains how bulk lamb is divided, lists the butcher lamb cuts of meat you can expect, and helps you decide which option suits your household.`],
      ['h2', `What is a quarter lamb?`],
      ['p', `A whole lamb is first split down the spine into two halves (sides). Each side can then be divided into a forequarter (shoulder, neck, ribs, rack and shank) and a hindquarter (loin, leg and the remaining shank). A "quarter lamb" therefore usually means either a forequarter or a hindquarter, or a mixed pack equal to a quarter of the animal. Because a typical dressed lamb weighs around 18 to 24 kg, a quarter is roughly 4.5 to 6 kg of meat and bone.`],
      ['p', `At the moment, we sell lamb in whole and half carcasses, and individual cuts. We do not list a quarter lamb as a separate product, but this guide explains the options so you can choose, and if you want to share a half lamb with family or friends, it can be split into two quarter portions.`],
      ['h2', `Lamb whole, half or quarter: what is included?`],
      ['p', `When you buy a lamb whole, you receive every cut. Typically, a whole lamb yields:`],
      ['ul', [
        `2 legs, which can be left whole, cut into half legs, butterflied or cut into leg steaks`,
        `2 shoulders, left whole, rolled, butterflied or cut into forequarter chops or diced`,
        `2 racks, left whole or cut into cutlets`,
        `Loin chops from the middle section`,
        `4 shanks`,
        `Neck, cut into chops or left whole`,
        `Ribs or breast`,
        `Trim, which can be minced or diced`,
      ]],
      ['p', `A half lamb gives you one of each of the paired cuts and half the rest. A quarter gives you either the front or back end, so it is worth deciding whether you prefer roasting and slow-cooking cuts (forequarter) or legs and chops (hindquarter).`],
      ['h2', `Butcher lamb cuts of meat explained`],
      ['h3', `Forequarter cuts`],
      ['p', `The forequarter contains the shoulder, neck, rack, ribs and fore shank. These cuts have more fat and connective tissue, making them perfect for slow roasting, curries, stews and braises. See our [lamb neck recipes](/blog/lamb-neck-recipes/), [diced lamb recipes](/blog/diced-lamb-recipes/) and [slow cooked lamb shanks](/blog/slow-cooked-lamb-shanks/).`],
      ['h3', `Hindquarter cuts`],
      ['p', `The hindquarter contains the leg, loin, rump and hind shank. These are leaner, tender cuts, ideal for roasting, grilling and pan-frying. Our [leg of lamb cooking time](/blog/leg-of-lamb-cooking-time/) and [lamb cutlets](/blog/how-do-you-cook-lamb-cutlets/) guides will help you cook them.`],
      ['h2', `How much freezer space do you need?`],
      ['p', `As a rough guide, allow about 30 litres (one cubic foot) of freezer space for every 10 to 12 kg of packaged meat. A half lamb fits in the freezer section of most family fridges if it is well organised; a whole lamb usually needs a dedicated chest or upright freezer. Vacuum-packed cuts are flatter and take less space than bulky trays.`],
      ['h2', `Is buying in bulk worth it?`],
      ['p', `Buying a half or whole lamb is usually cheaper per kilo than buying the same cuts individually, because you pay one price for every cut, from premium racks to economical shanks. It also gives you variety, less packaging and the convenience of a stocked freezer. The trade-offs are the upfront cost, the freezer space, and the need to plan meals around every cut, including the ones you might not normally buy.`],
      ['h2', `Halal meat food you can trust`],
      ['p', `When you buy lamb in bulk, you want to know exactly where it comes from and how it was handled. All of our lamb is certified halal by Halal Control Australia, cut in Greenacre, Sydney and delivered chilled. It is halal meat food you can serve to your family and guests with confidence.`],
      ['h2', `How to buy a whole lamb`],
      ['p', `If you decide to buy a whole lamb, our [whole lamb carcass](/product/whole-lamb-carcass/) can be delivered whole (for a spit roast, for example) or cut to your requirements. Our [half lamb carcass](/product/half-lamb-carcass/) is a great choice for smaller households. For aqeeqah and Qurbani, see our [whole lamb](/whole-lamb-aqeeqah-qurbani/) page. When ordering, tell us how you would like it cut, for example:`],
      ['ul', [
        `Legs: whole, half, butterflied or steaks`,
        `Shoulders: whole bone-in, boned and rolled, or diced`,
        `Racks: whole or cutlets`,
        `Loin: chops or rolled loin`,
        `Neck, shanks and ribs: left whole or cut`,
        `Trim: minced or diced`,
      ]],
      ['h2', `Storing bulk lamb`],
      ['ul', [
        `Freeze cuts you will not use within two to three days as soon as they arrive.`,
        `Label every pack with the cut and date.`,
        `Use within six to nine months for the best quality.`,
        `Thaw in the fridge, never on the bench.`,
        `Keep a list on the freezer door so you know what is left.`,
      ]],
      ['h2', `Quarter lamb questions`],
      ['h3', `How many meals does a quarter lamb make?`],
      ['p', `A quarter lamb typically provides 12 to 18 family meals, depending on the cuts and how you cook them.`],
      ['h3', `Can I choose the cuts?`],
      ['p', `Yes, with a whole or half lamb you can choose how each section is cut to suit the way you cook.`],
      ['h3', `How long does frozen lamb keep?`],
      ['p', `Well-wrapped lamb keeps for six to nine months in a freezer at minus 18°C.`],
      ['h2', `Sharing a lamb with family`],
      ['p', `Many families share a whole or half lamb between two or three households, which gives everyone bulk value without needing a large freezer. Decide in advance how you will split the cuts, for example one family takes the legs and racks while the other takes the shoulders, chops and shanks, or each gets an even mix. Ask for the cuts to be packed and labelled clearly, so the split is easy when the delivery arrives.`],
      ['p', `If you are unsure which cuts to choose, tell us how your family usually cooks, for example roasts on Sunday, curries midweek and grilled chops in summer, and we can suggest a cutting list that suits you.`],
      ['h2', `Order lamb online`],
      ['p', `Whole lamb, half lamb and every individual cut are in our [halal lamb range](/shop/lamb/), delivered chilled from Greenacre, Sydney, to anywhere in Australia, with free delivery on orders over $500.`],
    ],
  },
  {
    ...meta('lamb-chop-casserole'),
    title: 'Lamb Chop Casserole: An Easy, Hearty Family Recipe',
    seoTitle: 'Lamb Chop Casserole: Easy, Tender Recipe',
    excerpt: `A hearty lamb chop casserole with vegetables in a rich gravy: oven and slow cooker lamb chops casserole methods, the best chops to use and serving ideas.`,
    body: [
      ['p', `A lamb chop casserole is classic Australian comfort food: tender lamb chops slowly cooked with onions, carrots, potatoes and herbs in a rich, savoury gravy. It is economical, easy to prepare and fills the house with a wonderful aroma as it cooks. This guide gives you a reliable casserole with lamb chops, an oven and a slow cooker method, the best chops to use, and plenty of variations.`],
      ['h2', `Which chops to use`],
      ['p', `The best chops for a casserole are those with plenty of connective tissue and fat, which melt during slow cooking:`],
      ['ul', [
        `[Forequarter chops](/product/lamb-forequarter-chops/): the classic casserole chop; flavourful, economical and perfect for slow cooking.`,
        `[Lamb neck chops](/product/lamb-neck/): rich and gelatinous, ideal for a hearty casserole.`,
        `[Loin chops](/product/lamb-loin-chops/): leaner and more tender; they can be used, but reduce the cooking time to avoid drying them out.`,
      ]],
      ['h2', `Lamb chop casserole recipe`],
      ['p', `Serves four to six.`],
      ['ul', [
        `1.5 kg lamb forequarter or neck chops`,
        `3 tablespoons plain flour, seasoned with salt and pepper`,
        `2 tablespoons olive oil`,
        `2 onions, sliced, and 3 cloves garlic, crushed`,
        `3 carrots, 2 celery sticks and 1 parsnip, cut into chunks`,
        `500 g potatoes, cut into large chunks`,
        `2 tablespoons tomato paste`,
        `2 cups beef or lamb stock`,
        `1 tablespoon Worcestershire-style sauce (check it is alcohol-free) or soy sauce`,
        `2 bay leaves, a few sprigs of thyme and rosemary`,
        `1 cup frozen peas (optional) and chopped parsley to finish`,
      ]],
      ['h3', `Oven method`],
      ['p', `Heat the oven to 160°C. Toss the chops in the seasoned flour. Heat the oil in a large, ovenproof casserole dish and brown the chops in batches until golden; set aside. Add the onions to the pan and cook for 5 to 8 minutes until softened, then add the garlic for a minute. Stir in the tomato paste, then gradually add the stock and sauce, scraping up the browned bits.`],
      ['p', `Return the chops to the dish with the carrots, celery, parsnip, potatoes and herbs. Bring to a simmer, cover tightly and bake for 2 hours, until the lamb is tender and the vegetables are soft. Stir in the peas for the last 10 minutes. Skim off any fat, check the seasoning and scatter with parsley.`],
      ['h2', `Slow cooker lamb chops casserole`],
      ['p', `For a slow cooker lamb chops casserole, brown the floured chops and soften the onions and garlic in a pan first, then transfer everything to the slow cooker. Reduce the stock to 1 1/2 cups, because slow cookers lose very little liquid. Cook on low for 7 to 8 hours or on high for 4 to 5 hours. If the gravy is thin at the end, mix a tablespoon of cornflour with a little water, stir it in and cook on high, uncovered, for 15 to 20 minutes.`],
      ['h2', `Variations`],
      ['ul', [
        `Honey and mustard: replace the tomato paste with 2 tablespoons Dijon mustard and 1 tablespoon honey.`,
        `Curried: add 2 tablespoons curry powder with the onions and finish with coriander.`,
        `Mediterranean: add a can of chopped tomatoes, olives, oregano and a strip of lemon zest.`,
        `Mushroom: add 250 g sliced mushrooms with the onions and a splash of cream at the end.`,
        `Root vegetable: use sweet potato, turnip and swede for a hearty winter version.`,
      ]],
      ['h2', `Tips for a great casserole`],
      ['ul', [
        `Brown the chops well: it adds flavour to the gravy.`,
        `Keep the heat low and steady.`,
        `Cut vegetables into large chunks so they hold their shape.`,
        `Skim the fat before serving, or chill overnight and lift it off.`,
        `Make it a day ahead; the flavours deepen overnight.`,
      ]],
      ['h2', `Serving suggestions`],
      ['p', `Serve with creamy mashed potato, crusty bread or buttered rice to soak up the gravy, and steamed green beans or broccoli on the side. For a lighter meal, serve it in shallow bowls with a crisp green salad.`],
      ['h2', `A halal meat store you can rely on`],
      ['p', `A great casserole starts with good chops. As an online halal meat store and butcher in Greenacre, Sydney, we cut forequarter, neck and loin chops fresh and deliver them chilled across Australia. Every product is certified halal by Halal Control Australia.`],
      ['h2', `Grilling night: lamb shish kebab`],
      ['p', `Casserole is perfect for cold nights; for warmer evenings, try a lamb shish kebab instead. Cubes of leg or shoulder marinated in spices and grilled over hot coals make a quick and delicious meal. Our [lamb skewers](/blog/lamb-skewers/) guide has four marinades, and our [lamb cocktail kebabs](/product/lamb-cocktail-kebabs/) are ready to grill.`],
      ['h2', `Lamb chop casserole questions`],
      ['h3', `Can I make it on the stove?`],
      ['p', `Yes. Simmer gently, covered, for 1.5 to 2 hours, stirring occasionally and adding a little stock if needed.`],
      ['h3', `Can I freeze lamb chop casserole?`],
      ['p', `Yes, for up to three months. Potatoes can become slightly grainy after freezing, so you can leave them out and serve the casserole with fresh mash instead.`],
      ['h3', `Do I need to remove the bones?`],
      ['p', `No. The bones add flavour; the meat will fall off them easily after slow cooking.`],
      ['h2', `Feeding a family on a budget`],
      ['p', `Lamb chop casserole is one of the most economical family meals you can make with lamb. Forequarter chops are inexpensive, and the vegetables stretch the meat further. To make it go even further, add a can of drained chickpeas or cannellini beans, an extra potato or two, or a cup of pearl barley with an extra cup of stock. Leftovers make a great lunch the next day, spooned over rice or mashed potato.`],
      ['p', `For children, cut the vegetables smaller and pull the meat off the bones before serving, so it is easy to eat. A sprinkle of grated cheese on top is a popular finishing touch with younger diners.`],
      ['h2', `Dumplings or pastry topping`],
      ['p', `For an extra-hearty winter meal, top the casserole with herb dumplings for the last 25 minutes. Mix 1 cup self-raising flour with 50 g grated cold butter, a pinch of salt and some chopped parsley, then add enough milk to form a soft dough. Drop spoonfuls onto the simmering casserole, cover and cook until the dumplings are puffed and cooked through. Alternatively, transfer the cooked casserole to a pie dish, cover with puff pastry, brush with egg and bake at 200°C for 25 minutes until golden.`],
      ['h2', `Buy halal lamb chops online`],
      ['p', `Forequarter, neck and loin chops are in our [halal lamb range](/shop/lamb/), delivered chilled from Greenacre, Sydney, to anywhere in Australia. For more chop recipes, see our [slow cooked lamb chops](/blog/slow-cooked-lamb-chops/) guide.`],
    ],
  },
  {
    ...meta('marinade-for-mutton-chops'),
    title: 'Marinade for Mutton Chops: Baked, Slow-Cooked and Neck Chops',
    seoTitle: 'Best Marinade for Mutton Chops and Recipes',
    excerpt: `A marinade for mutton chops that tenderises and flavours: yoghurt and spice, baked mutton chops, a mutton chops slow cooker method and neck chops.`,
    body: [
      ['p', `Mutton is meat from mature sheep, usually over two years old. It has a deeper, richer and more pronounced flavour than lamb, and its meat is firmer, so it rewards a good marinade and gentle, slow cooking. Mutton is a staple in South Asian, Middle Eastern and African kitchens, where it is used for curries, roasts and slow-cooked dishes. This guide gives you the best marinade for mutton chops, explains how to bake and slow cook them, and includes a mutton neck chops recipe.`],
      ['h2', `Mutton vs lamb`],
      ['p', `Lamb comes from younger sheep, usually under a year old, and is tender with a mild flavour. Mutton comes from older animals; it is darker in colour, more strongly flavoured and has more connective tissue, so it needs longer cooking. Many cooks prefer mutton for curries and stews because its flavour stands up to bold spices. In some countries, the word mutton is also used for goat meat, which is why you may see the term goat mutton on menus in South Asian restaurants. Our [whole mutton carcass](/product/whole-mutton-meat-carcass/) is ideal for families and caterers who cook mutton regularly.`],
      ['h2', `Why marinate mutton?`],
      ['p', `A good marinade does three things for mutton: it tenderises the surface, especially if it contains yoghurt or papaya; it adds flavour; and it helps the meat brown beautifully. Because mutton has a stronger flavour than lamb, it pairs well with assertive spices like garam masala, cumin, coriander, chilli, ginger and garlic.`],
      ['h2', `The best marinade for mutton chops`],
      ['ul', [
        `1 kg mutton chops (loin, forequarter or neck)`,
        `1 cup thick plain yoghurt`,
        `1 tablespoon each ginger paste and garlic paste`,
        `1 tablespoon raw papaya paste (optional, a powerful natural tenderiser)`,
        `2 teaspoons Kashmiri chilli powder and 1 teaspoon garam masala`,
        `1 teaspoon each ground cumin and coriander, and 1/2 teaspoon turmeric`,
        `Juice of 1 lemon, 2 tablespoons oil and 1 1/2 teaspoons salt`,
      ]],
      ['p', `Mix everything together and coat the chops thoroughly, massaging the marinade into the meat. Cover and refrigerate for at least 4 hours, ideally overnight. If you use papaya paste, limit marinating to 4 to 6 hours, as it is very strong.`],
      ['h2', `Baked mutton chops`],
      ['p', `For baked mutton chops, heat the oven to 180°C. Arrange the marinated chops in a single layer in a roasting dish, add half a cup of water to the dish, cover tightly with foil, and bake for 1.5 to 2 hours until tender. Uncover, increase the oven to 220°C, baste with the juices, and bake for another 15 to 20 minutes until browned and slightly charred at the edges. Serve with naan, rice, sliced onions and lemon.`],
      ['h2', `Mutton chops slow cooker method`],
      ['p', `For a mutton chops slow cooker version, brown the marinated chops in a hot pan first for colour. Fry a sliced onion until golden, add a chopped tomato and cook until soft. Place everything in the slow cooker with half a cup of water and cook on low for 7 to 8 hours or high for 4 to 5 hours, until the meat falls off the bone. Finish with fresh coriander and green chillies.`],
      ['h2', `Mutton neck chops recipe`],
      ['p', `This mutton neck chops recipe makes a rich, homestyle curry. Fry 2 sliced onions in 3 tablespoons oil until deep golden. Add a tablespoon each of ginger and garlic paste, then 2 teaspoons chilli, 1 teaspoon each cumin, coriander and garam masala, and 1/2 teaspoon turmeric. Add 1.2 kg marinated neck chops and cook over high heat for 10 minutes, stirring, until browned. Add 2 chopped tomatoes and cook until they break down, then add water to cover. Simmer gently, covered, for 2 to 2.5 hours until tender. Finish with garam masala and coriander.`],
      ['h2', `Is goat shoulder good for curry?`],
      ['p', `Customers often ask: is goat shoulder good for curry, compared with mutton? The answer is yes. Goat shoulder has a good balance of meat, fat and connective tissue and becomes tender and flavourful in a curry, much like mutton. Bone-in pieces give the richest sauce. See our [goat shoulder](/product/goat-shoulder-square-cut/), [diced goat](/product/diced-goat-bone-in/) and [goat meat curry cuts guide](/blog/goat-meat-curry-cuts-guide/).`],
      ['h2', `Goats meat and mutton: interchangeable in many recipes`],
      ['p', `Goats meat and mutton can be used interchangeably in most of these recipes. Goat is leaner and slightly gamier; mutton is richer and fattier. Both need slow cooking. Adjust cooking times as needed: goat may need a little longer to become tender. Our [goat range](/shop/goat-meat-for-sale/) has bone-in and boneless cuts.`],
      ['h2', `Steak night: halal steak Sydney`],
      ['p', `Mutton is perfect for slow-cooked meals; for a quick dinner, a good steak is hard to beat. If you are searching for halal steak Sydney delivery, our [halal beef range](/shop/halal-beef/) includes scotch fillet, porterhouse, rump and Wagyu, all certified halal by Halal Control Australia and delivered from Greenacre.`],
      ['h2', `Marinade for mutton chops questions`],
      ['h3', `How long should mutton marinate?`],
      ['p', `At least 4 hours, and ideally overnight, for yoghurt-based marinades. Limit papaya-based marinades to 4 to 6 hours.`],
      ['h3', `Can I grill mutton chops?`],
      ['p', `Yes, after marinating. Grill over medium heat and cook to medium or well done. Mutton is firmer than lamb, so the marinade really helps.`],
      ['h3', `How do I reduce the strong smell of mutton?`],
      ['p', `Trim excess fat, marinate in yoghurt with ginger, garlic and lemon, and cook with aromatic spices. A quick blanch in boiling water before cooking can also help.`],
      ['h2', `Serving mutton chops`],
      ['p', `Mutton chops are rich, so serve them with fresh, sharp sides: sliced onions with lemon and chilli, a cucumber and tomato salad, mint chutney or raita. Basmati rice, naan or paratha soak up the sauce, and a simple dal makes the meal more filling. For a festive spread, serve the baked chops alongside biryani and a selection of chutneys.`],
      ['p', `Leftover chops keep for three days in the fridge and reheat well, covered, in a 160°C oven with a splash of water. They also freeze for up to three months in their sauce.`],
      ['p', `For entertaining, the baked chops can be marinated a day ahead and cooked while guests arrive, leaving you free to prepare the rice and sides.`],
      ['h2', `Buy halal mutton and goat online`],
      ['p', `Whole mutton, goat cuts and lamb chops are available in our [halal lamb range](/shop/lamb/) and [goat range](/shop/goat-meat-for-sale/), delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('mutton-stew-slow-cooker'),
    title: 'Mutton Stew Slow Cooker Recipe: Rich, Tender and Easy',
    seoTitle: 'Mutton Stew Slow Cooker Recipe: Easy Guide',
    excerpt: `A mutton stew slow cooker recipe: mutton neck stew with vegetables, slow cooked mutton chops, using mutton neck fillet, plus goat diced alternatives.`,
    body: [
      ['p', `Mutton is perfect for the slow cooker. Its firm texture and rich flavour need long, gentle cooking, and the slow cooker delivers exactly that: tender meat, a deeply savoury sauce and almost no effort. Whether you prefer a Western-style stew with root vegetables or a fragrant South Asian curry, this mutton stew slow cooker guide covers it all, including a mutton neck stew, slow cooked mutton chops and tips for using mutton neck fillet.`],
      ['h2', `What is mutton?`],
      ['p', `Mutton is meat from sheep older than about two years. It is darker and more flavourful than lamb, with more connective tissue and fat, which makes it ideal for slow cooking. Meat mutton lovers prize its depth of flavour, which stands up to bold spices and long braises. Our [whole mutton carcass](/product/whole-mutton-meat-carcass/) is popular with families and caterers who cook mutton regularly.`],
      ['h2', `Best cuts for mutton stew`],
      ['ul', [
        `Neck: bone-in neck pieces give a rich, gelatinous sauce.`,
        `Mutton neck fillet: the boneless eye of the neck, tender and well marbled after slow cooking.`,
        `Shoulder: well balanced, perfect for diced stew meat.`,
        `Chops: forequarter and neck chops are excellent slow cooked.`,
        `Shanks: meaty and full of flavour.`,
      ]],
      ['h2', `Mutton neck stew (slow cooker)`],
      ['p', `Serves six.`],
      ['ul', [
        `1.5 kg mutton neck pieces or chops`,
        `2 tablespoons plain flour, salt and pepper`,
        `2 tablespoons oil`,
        `2 onions, 3 carrots, 2 celery sticks and 2 parsnips, cut into chunks`,
        `600 g potatoes, cut into large chunks`,
        `3 cloves garlic, crushed, and 2 tablespoons tomato paste`,
        `2 cups beef or lamb stock`,
        `2 bay leaves, thyme and rosemary`,
      ]],
      ['p', `Toss the mutton in seasoned flour and brown well in batches in a hot pan; transfer to the slow cooker. Soften the onions in the same pan, add garlic and tomato paste, then pour in the stock and scrape up the browned bits. Pour the mixture over the mutton, add the vegetables and herbs, and stir. Cook on low for 8 to 10 hours or high for 5 to 6 hours, until the mutton is falling off the bone. Skim the fat, season to taste and serve with crusty bread.`],
      ['h2', `Slow cooked mutton chops, curry style`],
      ['p', `For slow cooked mutton chops with South Asian flavours, marinate 1.2 kg chops in yoghurt, ginger-garlic paste, chilli, turmeric and salt for a few hours. Fry 2 onions until deep golden, add garam masala, cumin and coriander, then tomatoes. Brown the chops briefly, then transfer everything to the slow cooker with half a cup of water. Cook on low for 7 to 8 hours. Finish with coriander, green chilli and a squeeze of lemon. Our [marinade for mutton chops](/blog/marinade-for-mutton-chops/) guide has more ideas.`],
      ['h2', `Using mutton neck fillet`],
      ['p', `Mutton neck fillet is a boneless, well-marbled cut that becomes tender and juicy in the slow cooker. Cut it into 4 cm chunks for stews and curries, or cook it whole and slice it. Because it has no bone, it cooks a little faster than bone-in neck: allow 6 to 7 hours on low.`],
      ['h2', `Tips for the best mutton stew`],
      ['ul', [
        `Brown the meat well for flavour and colour.`,
        `Do not add too much liquid; slow cookers lose very little to evaporation.`,
        `Trim excess fat before cooking, and skim the stew afterwards.`,
        `Add delicate vegetables, such as peas or spinach, in the last 30 minutes.`,
        `Cook a day ahead: the flavour improves overnight and the fat is easy to remove.`,
      ]],
      ['h2', `Goat diced: a great alternative`],
      ['p', `If you cannot find mutton, goat diced into chunks is an excellent alternative. Goat is leaner and slightly gamier than mutton but cooks in a very similar way in the slow cooker. Our [diced goat (bone-in)](/product/diced-goat-bone-in/) is perfect for stews and curries, and the [goat curry cut catering pack](/product/goat-curry-cut-catering-pack/) suits larger gatherings. See our [slow cooked goat recipes](/blog/slow-cooked-goat-recipes/) for more.`],
      ['h2', `Boer goat meat for sale?`],
      ['p', `Customers sometimes search for boer goat meat for sale, Boer being a popular meat goat breed. We do not label our goat by breed, but every piece of goat we sell is certified halal by Halal Control Australia and cut fresh in Greenacre, Sydney. Browse our [goat range](/shop/goat-meat-for-sale/) for whole and half goat, shoulders, legs, racks, shanks and diced goat.`],
      ['h2', `Premium halal meat for slow cooking`],
      ['p', `Slow cooking turns economical cuts into something special, but it still pays to start with premium halal meat. Fresh, well-trimmed mutton, lamb and goat give a cleaner-tasting sauce and better texture. All of our meat is certified halal by Halal Control Australia and delivered chilled across Australia.`],
      ['h2', `Mutton stew questions`],
      ['h3', `How long does mutton take in a slow cooker?`],
      ['p', `Bone-in mutton takes about 8 to 10 hours on low, or 5 to 6 hours on high. Boneless cuts may need slightly less.`],
      ['h3', `Can I cook mutton from frozen in a slow cooker?`],
      ['p', `No. Thaw it in the fridge first, as frozen meat stays too long in the temperature danger zone in a slow cooker.`],
      ['h3', `Can I freeze mutton stew?`],
      ['p', `Yes, for up to three months. Potatoes can become grainy after freezing, so you might prefer to add fresh potatoes when reheating.`],
      ['h2', `What to serve with mutton stew`],
      ['p', `For a Western-style mutton stew, serve crusty bread, buttery mashed potato or creamy polenta, with steamed greens on the side. For curry-style slow cooked mutton, serve basmati rice, naan or roti, with raita and a simple salad. Pickles and chutneys add brightness. A squeeze of lemon and a handful of fresh herbs just before serving lifts the rich flavour of the mutton.`],
      ['p', `Leftover stew can be turned into a pie with a puff pastry lid, or blended with extra stock into a hearty soup.`],
      ['h2', `Adapting the stew for different tastes`],
      ['p', `The basic stew is mild and family-friendly. For more warmth, add a teaspoon each of cumin, coriander and paprika with the onions, or stir in a spoon of harissa. For a Middle Eastern twist, add cinnamon, allspice and a handful of dried apricots, and finish with toasted almonds. For extra greens, stir in spinach or kale for the last 20 minutes.`],
      ['h2', `Buy halal mutton and goat online`],
      ['p', `Whole mutton, goat cuts and lamb are available in our [halal lamb range](/shop/lamb/) and [goat range](/shop/goat-meat-for-sale/), delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
]
